package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class ParticipantWithdrawalAndPagingTest {
 @Test void withdrawalChecksOwnershipConfirmationRevisionAndPreservesCompletedResults(){
  var f=new TeamTournamentTest();var t=f.cup();f.lock(t);var finished=t.matches.getFirst();TournamentFixtures.finish(finished,finished.participantA.participantId(),4,2);var participant=finished.participantA;var service=new ParticipantWithdrawalService(f.tournaments,f.owned,f.accounts);var auth=participant.ownerUserId().equals(f.a.id().value())?f.aa:f.bb;var other=auth==f.aa?f.bb:f.aa;
  assertThatThrownBy(()->service.withdraw(other,t.id,t.revision,participant.participantId(),true)).hasMessage("TOURNAMENT_FORBIDDEN");
  assertThatThrownBy(()->service.withdraw(auth,t.id,t.revision,participant.participantId(),false)).hasMessage("WITHDRAW_CONFIRMATION_REQUIRED");
  assertThatThrownBy(()->service.withdraw(auth,t.id,-1L,participant.participantId(),true)).hasMessage("STALE_TOURNAMENT_REVISION");
  service.withdraw(auth,t.id,t.revision,participant.participantId(),true);assertThat(t.operations.active(participant.participantId())).isFalse();assertThat(finished.winnerParticipantId).isEqualTo(participant.participantId());assertThat(finished.remainingA).isEqualTo(4);long revision=t.revision;service.withdraw(auth,t.id,revision,participant.participantId(),true);assertThat(t.revision).isEqualTo(revision);
 }
 @Test void failedCommitRollsBackWithdrawalForfeitsAndAudit(){var f=new TeamTournamentTest();var t=f.cup();f.lock(t);var participant=t.matches.getFirst().participantA;var auth=participant.ownerUserId().equals(f.a.id().value())?f.aa:f.bb;long revision=t.revision;int audit=t.operations.audit().size();doThrow(new IllegalStateException("offline")).when(f.repository).save(any());assertThatThrownBy(()->new ParticipantWithdrawalService(f.tournaments,f.owned,f.accounts).withdraw(auth,t.id,revision,participant.participantId(),true)).hasMessage("offline");assertThat(t.operations.active(participant.participantId())).isTrue();assertThat(t.revision).isEqualTo(revision);assertThat(t.operations.audit()).hasSize(audit);assertThat(t.matches).allMatch(m->m.status==TournamentMatch.Status.PENDING);}
 @Test void pendingGamesForfeitWithoutFakeReplayAndLiveGamesWaitForExecution(){var f=new TeamTournamentTest();var t=f.cup();f.lock(t);var live=t.matches.getFirst();live.status=TournamentMatch.Status.RUNNING;var participant=live.participantA;var extra=new TournamentMatch(UUID.randomUUID().toString(),t.id,participant,live.participantB);extra.round=2;t.matches.add(extra);var auth=participant.ownerUserId().equals(f.a.id().value())?f.aa:f.bb;new ParticipantWithdrawalService(f.tournaments,f.owned,f.accounts).withdraw(auth,t.id,t.revision,participant.participantId(),true);assertThat(live.status).isEqualTo(TournamentMatch.Status.RUNNING);assertThat(extra.status).isEqualTo(TournamentMatch.Status.FINISHED);assertThat(extra.decisionReason).isEqualTo("FORFEIT");assertThat(extra.winnerParticipantId).isEqualTo(live.participantB.participantId());assertThat(extra.historyMatchId).isNull();}
 @Test void serverPagesHaveStableNonOverlappingRowsAndOwnedFiltersAndRejectInvalidBounds(){var f=new TeamTournamentTest();var t=f.cup();f.lock(t);var service=new TournamentMatchPageService(f.tournaments,f.accounts);var first=service.page(f.aa,t.id,0,2,null,null,null,false,"round",false);var second=service.page(f.aa,t.id,1,2,null,null,null,false,"round",false);assertThat(first.get("total")).isEqualTo(3);assertThat((List<?>)first.get("items")).hasSize(2);assertThat((List<?>)second.get("items")).hasSize(1);assertThat(new HashSet<>((List<?>)first.get("items"))).doesNotContainAnyElementsOf((List)second.get("items"));assertThat((List<?>)service.page(f.aa,t.id,0,20,99,null,null,false,"time",false).get("items")).isEmpty();assertThat((List<?>)service.page(f.aa,t.id,0,20,null,null,null,true,"round",false).get("items")).hasSize(3);assertThatThrownBy(()->service.page(f.aa,t.id,0,51,null,null,null,false,"round",false)).hasMessage("INVALID_PAGING");assertThatThrownBy(()->service.page(f.aa,t.id,-1,20,null,null,null,false,"round",false)).hasMessage("INVALID_PAGING");}
 @Test void summaryDoesNotSerializeFinishedMatchHistoryOrItsSeries(){var f=new TeamTournamentTest();var t=f.cup();f.lock(t);for(var m:t.matches)TournamentFixtures.finish(m,m.participantA.participantId(),1,0);var summary=f.tournaments.summary(t);assertThat(summary.get("paged")).isEqualTo(true);assertThat((List<?>)summary.get("matches")).isEmpty();assertThat((List<?>)summary.get("series")).isEmpty();assertThat((List<?>)f.tournaments.view(t).get("matches")).hasSize(3);}
}
